sys_ws_operation.operation_script:
(function process( /*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {

    var requestData = request.body.data;

    var emailBody = build_emailBody(requestData);

    // implement resource here
    gs.info('nicky_demo: ' + emailBody);

    var grEmail = null;
    for (var i = 0; i < 1000; i++) {
        grEmail = waitEmailRecord();
        if (grEmail) {
            break;
        }
        var startTime = new Date().getTime(); 
        while (new Date().getTime() - startTime < 10) {
			var tmp = startTime;
        }
    }

    if (grEmail) {
        sendMail(emailBody, grEmail);
        grEmail.type = 'send-ignored';
        grEmail.update();
        gs.info('nicky_demo: Email Sys ID:' + grEmail.sys_id);
    } else {
        gs.info('nicky_demo: No email:');
    }

    function sendMail(emailBody, grEmail) {
        try {
            //var mailProperties = JSON.parse(gs.getProperty('x_hsb11_global_monthly.dataExtraction_userLoginHistories_email_properties'));
            var mailProperties = JSON.parse(gs.getProperty('x_hsb11_mss_c_atf.demo_email_properties'));

            var inputs = {};
            //format of to/cc/bcc recipients '\"HSSQTrack050@adrestest.addev.hsbc\",\"HSSQTrack050@adrestest.addev.hsbc\"'
            inputs['torecipients'] = mailProperties.torecipients; // String 
            inputs['ccrecipients'] = mailProperties.ccrecipients; // String 
            inputs['emlsender'] = mailProperties.sender; // String 
            inputs['emlsubject'] = grEmail.getValue('subject'); // String 
            inputs['bccrecipients'] = mailProperties.bccrecipients; // String 
            inputs['emlbody'] = grEmail.body; // String 
            inputs['classification'] = mailProperties.classification; // String 
            inputs['servicenowid'] = mailProperties.servicenowid; // String 
            gs.info('nicky_demo: 1');
            // Start Asynchronously: Uncomment to run in background. Code snippet will not have access to outputs.
            // sn_fd.FlowAPI.getRunner().action('x_hsb11_hsbcmss_qw.qtrack_action').inBackground().withInputs(inputs).run();

            // Execute Synchronously: Run in foreground. Code snippet has access to outputs.
            var result = sn_fd.FlowAPI.getRunner().action('x_hsb11_hsbcmss_qw.qtrack_action').inForeground().withInputs(inputs).run();
            var outputs = result.getOutputs();
            gs.info('nicky_demo: 2');
            // Get Outputs:
            // Note: outputs can only be retrieved when executing synchronously.
            var responsebody = outputs['responsebody']; // String
            var statuscode = outputs['statuscode']; // String
            var errormessage = outputs['errormessage']; // String
            var errorcode = outputs['errorcode']; // String
            gs.info("nicky_demo:" + responsebody + statuscode + errormessage + errorcode);

        } catch (ex) {
            var message = ex.getMessage();
            gs.error('nicky_demo: ' + message);
        }

        var rlt = {
            "status": 200,
            "message": "Request successful!",
            "response": {
                "result": "Success",
                "data": {
                    "status": "Success"
                }
            }
        };

        response.setBody(rlt);
    }

    function build_emailBody(requestBody) {
        var requestPlayload = request.body.data.PAYLOAD;
        var requestHeader = request.body.data.HEADER;
        var emailBody = "";

        // Header
        var msgID = requestHeader.MessageID;
        var eventType = requestHeader.EventType;
        var source = requestHeader.Source;
        var objectType = requestHeader.ObjectType;
        var objectIDType = requestHeader.ObjectIDType;
        var objectID = requestHeader.ObjectID;
        var objectVersion = requestHeader.ObjectVersion;
        var eventStatus = requestHeader.EventStatus;
        var eventDateTime = requestHeader.EventDateTime;
        var etcService = requestHeader.AdditionalAttributes.ETC_Service;
        var counterpartyCode = requestHeader.AdditionalAttributes.COUNTERPARTY_CODE;

        var str_header = "MessageID:" + msgID +
            ", <br>EventType:" + eventType +
            ", <br>Source:" + source +
            ", <br>ObjectType:" + objectType +
            ", <br>ObjectIDType:" + objectIDType +
            ", <br>ObjectID:" + objectID +
            ", <br>ObjectVersion:" + objectVersion +
            ", <br>EventStatus:" + eventStatus +
            ", <br>EventDateTime:" + eventDateTime +
            ", <br>ETC_Service:" + etcService +
            ", <br>COUNTERPARTY_CODE:" + counterpartyCode;

        // Play Load
        var MESSAGE_SOURCE = requestPlayload.MESSAGE_SOURCE;
        var MESSAGE_TYPE = requestPlayload.MESSAGE_TYPE;
        var DATASTREAM_REF = requestPlayload.DATASTREAM_REF;
        var MORE = requestPlayload.MORE;
        var CTAC_EVENT = requestPlayload.CTAC_EVENT;
        var ETC_SERVICE = requestPlayload.ETC_SERVICE;
        var CTAC_TRADE_STATUS = requestPlayload.CTAC_TRADE_STATUS;
        var CTAC_TRANS_MSG_ID = requestPlayload.CTAC_TRANS_MSG_ID;
        var CTAC_TRANS_MSG_P0 = requestPlayload.CTAC_TRANS_MSG_P0;
        var CTAC_TRANS_MSG_P1 = requestPlayload.CTAC_TRANS_MSG_P1;
        var CTAC_TRANS_MSG_P2 = requestPlayload.CTAC_TRANS_MSG_P2;
        var CTAC_TRANS_MSG_P3 = requestPlayload.CTAC_TRANS_MSG_P3;
        var CTAC_TRANS_MSG_P4 = requestPlayload.CTAC_TRANS_MSG_P4;
        var CTAC_TRANS_MSG_P5 = requestPlayload.CTAC_TRANS_MSG_P5;
        var CTAC_TRANS_MSG_P6 = requestPlayload.CTAC_TRANS_MSG_P6;
        var CTAC_TRANS_MSG_P7 = requestPlayload.CTAC_TRANS_MSG_P7;
        var CTAC_TRANS_MSG_P8 = requestPlayload.CTAC_TRANS_MSG_P8;
        var CTAC_TRANS_MSG_P9 = requestPlayload.CTAC_TRANS_MSG_P9;
        var CTAC_ALLOCS_AGAINST_MSN = requestPlayload.CTAC_ALLOCS_AGAINST_MSN;
        var EVENT_DESCRIPTION = requestPlayload.EVENT_DESCRIPTION;
        var CTAC_TRADE_DID = requestPlayload.CTAC_TRADE_DID;
        var CTAC_TRADE_VERSION = requestPlayload.CTAC_TRADE_VERSION;
        var CTAC_ALLOCATION_DID = requestPlayload.CTAC_ALLOCATION_DID;
        var CTAC_ALLOCATION_VERSION = requestPlayload.CTAC_ALLOCATION_VERSION;
        var CTAC_AUDIT_DID = requestPlayload.CTAC_AUDIT_DID;
        var IAW_EXCEPTION_TYPE = requestPlayload.IAW_EXCEPTION_TYPE;
        var IAW_EXCEPTION_STATUS = requestPlayload.IAW_EXCEPTION_STATUS;
        var SUMMARY = requestPlayload.SUMMARY;
        var STREAM_NAME = requestPlayload.STREAM_NAME;

        var CTAC_TRADE_AUDIT = requestPlayload.CTAC_TRADE_AUDIT;
        var CTAC_TRADE_CHARGES = requestPlayload.CTAC_TRADE_CHARGES;
        var CTAC_CTM_TRADE_LEVEL_FLD_COMP = requestPlayload.CTAC_CTM_TRADE_LEVEL_FLD_COMP;

        if (CTAC_TRADE_AUDIT && CTAC_TRADE_AUDIT.length > 0) {
            var COUNTERPARTY_CODE = CTAC_TRADE_AUDIT[0].COUNTERPARTY_CODE;
            var COUNTERPARTY_DESCRIPTION = CTAC_TRADE_AUDIT[0].COUNTERPARTY_DESCRIPTION;
            var ETC_SERVICE_AUDIT = CTAC_TRADE_AUDIT[0].ETC_SERVICE;
            var INSTRUMENT_DESCRIPTION = CTAC_TRADE_AUDIT[0].INSTRUMENT_DESCRIPTION;
        }

        if (CTAC_TRADE_CHARGES && CTAC_TRADE_CHARGES.length > 0) {
            var CHARGE_ID = CTAC_TRADE_CHARGES[0].CHARGE_ID;
            var CHARGE_AMOUNT = CTAC_TRADE_CHARGES[0].CHARGE_AMOUNT;
            var CALCULATION_VALUE = CTAC_TRADE_CHARGES[0].CALCULATION_VALUE;
            var CALCULATION_METHOD = CTAC_TRADE_CHARGES[0].CALCULATION_METHOD;
        }

        if (CTAC_CTM_TRADE_LEVEL_FLD_COMP && CTAC_CTM_TRADE_LEVEL_FLD_COMP.length > 0) {
            var CTAC_CTM_TL_ID = CTAC_CTM_TRADE_LEVEL_FLD_COMP[0].CTAC_CTM_TL_ID;
            var CTAC_CTM_FIELD_NAME = CTAC_CTM_TRADE_LEVEL_FLD_COMP[0].CTAC_CTM_FIELD_NAME;
            var CTAC_CTM_BROKER_VALUE = CTAC_CTM_TRADE_LEVEL_FLD_COMP[0].CTAC_CTM_BROKER_VALUE;
            var CTAC_CTM_CPTY_VALUE = CTAC_CTM_TRADE_LEVEL_FLD_COMP[0].CTAC_CTM_CPTY_VALUE;
            var CTAC_CTM_MACH_STATUS = CTAC_CTM_TRADE_LEVEL_FLD_COMP[0].CTAC_CTM_MACH_STATUS;
            var CTAC_CTM_MACH_RULE = CTAC_CTM_TRADE_LEVEL_FLD_COMP[0].CTAC_CTM_MACH_RULE;
        }

        var str_playload =
            "MESSAGE_SOURCE: " + MESSAGE_SOURCE + ",<br>" +
            "MESSAGE_TYPE: " + MESSAGE_TYPE + ",<br>" +
            "DATASTREAM_REF: " + DATASTREAM_REF + ",<br>" +
            "MORE: " + MORE + ",<br>" +
            "CTAC_EVENT: " + CTAC_EVENT + ",<br>" +
            "ETC_SERVICE: " + ETC_SERVICE + ",<br>" +
            "CTAC_TRADE_STATUS: " + CTAC_TRADE_STATUS + ",<br>" +
            "CTAC_TRANS_MSG_ID: " + CTAC_TRANS_MSG_ID + ",<br>" +
            "CTAC_TRANS_MSG_P0: " + CTAC_TRANS_MSG_P0 + ",<br>" +
            "CTAC_TRANS_MSG_P1: " + CTAC_TRANS_MSG_P1 + ",<br>" +
            "CTAC_TRANS_MSG_P2: " + CTAC_TRANS_MSG_P2 + ",<br>" +
            "CTAC_TRANS_MSG_P3: " + CTAC_TRANS_MSG_P3 + ",<br>" +
            "CTAC_TRANS_MSG_P4: " + CTAC_TRANS_MSG_P4 + ",<br>" +
            "CTAC_TRANS_MSG_P5: " + CTAC_TRANS_MSG_P5 + ",<br>" +
            "CTAC_TRANS_MSG_P6: " + CTAC_TRANS_MSG_P6 + ",<br>" +
            "CTAC_TRANS_MSG_P7: " + CTAC_TRANS_MSG_P7 + ",<br>" +
            "CTAC_TRANS_MSG_P8: " + CTAC_TRANS_MSG_P8 + ",<br>" +
            "CTAC_TRANS_MSG_P9: " + CTAC_TRANS_MSG_P9 + ",<br>" +
            "CTAC_ALLOCS_AGAINST_MSN: " + CTAC_ALLOCS_AGAINST_MSN + ",<br>" +
            "EVENT_DESCRIPTION: " + EVENT_DESCRIPTION + ",<br>" +
            "CTAC_TRADE_DID: " + CTAC_TRADE_DID + ",<br>" +
            "CTAC_TRADE_VERSION: " + CTAC_TRADE_VERSION + ",<br>" +
            "CTAC_ALLOCATION_DID: " + CTAC_ALLOCATION_DID + ",<br>" +
            "CTAC_ALLOCATION_VERSION: " + CTAC_ALLOCATION_VERSION + ",<br>" +
            "CTAC_AUDIT_DID: " + CTAC_AUDIT_DID + ",<br>" +
            "IAW_EXCEPTION_TYPE: " + IAW_EXCEPTION_TYPE + ",<br>" +
            "IAW_EXCEPTION_STATUS: " + IAW_EXCEPTION_STATUS + ",<br>" +
            "SUMMARY: " + SUMMARY + ",<br>" +
            "STREAM_NAME: " + STREAM_NAME;

        if (CTAC_TRADE_AUDIT && CTAC_TRADE_AUDIT.length > 0) {
            str_playload += ",<br>COUNTERPARTY_CODE: " + CTAC_TRADE_AUDIT[0].COUNTERPARTY_CODE + ",<br>" +
                "COUNTERPARTY_DESCRIPTION: " + CTAC_TRADE_AUDIT[0].COUNTERPARTY_DESCRIPTION + ",<br>" +
                "ETC_SERVICE_AUDIT: " + CTAC_TRADE_AUDIT[0].ETC_SERVICE + ",<br>" +
                "INSTRUMENT_DESCRIPTION: " + CTAC_TRADE_AUDIT[0].INSTRUMENT_DESCRIPTION;
        }

        if (CTAC_TRADE_CHARGES && CTAC_TRADE_CHARGES.length > 0) {
            str_playload += ",<br>CHARGE_ID: " + CTAC_TRADE_CHARGES[0].CHARGE_ID + ",<br>" +
                "CHARGE_AMOUNT: " + CTAC_TRADE_CHARGES[0].CHARGE_AMOUNT + ",<br>" +
                "CALCULATION_VALUE: " + CTAC_TRADE_CHARGES[0].CALCULATION_VALUE + ",<br>" +
                "CALCULATION_METHOD: " + CTAC_TRADE_CHARGES[0].CALCULATION_METHOD;
        }

        if (CTAC_CTM_TRADE_LEVEL_FLD_COMP && CTAC_CTM_TRADE_LEVEL_FLD_COMP.length > 0) {
            str_playload += ",<br>CTAC_CTM_TL_ID: " + CTAC_CTM_TRADE_LEVEL_FLD_COMP[0].CTAC_CTM_TL_ID + ",<br>" +
                "CTAC_CTM_FIELD_NAME: " + CTAC_CTM_TRADE_LEVEL_FLD_COMP[0].CTAC_CTM_FIELD_NAME + ",<br>" +
                "CTAC_CTM_BROKER_VALUE: " + CTAC_CTM_TRADE_LEVEL_FLD_COMP[0].CTAC_CTM_BROKER_VALUE + ",<br>" +
                "CTAC_CTM_CPTY_VALUE: " + CTAC_CTM_TRADE_LEVEL_FLD_COMP[0].CTAC_CTM_CPTY_VALUE + ",<br>" +
                "CTAC_CTM_MACH_STATUS: " + CTAC_CTM_TRADE_LEVEL_FLD_COMP[0].CTAC_CTM_MACH_STATUS + ",<br>" +
                "CTAC_CTM_MACH_RULE: " + CTAC_CTM_TRADE_LEVEL_FLD_COMP[0].CTAC_CTM_MACH_RULE;
        }

        var gr = new GlideRecord('x_hsb11_mss_c_atf_demo_trade_case');
        gr.initialize();
        gr.setValue("message_source", MESSAGE_SOURCE);
        gr.setValue("message_typemessage_type", MESSAGE_TYPE);
        gr.setValue("datastream_refdatastream_ref", DATASTREAM_REF);
        gr.setValue("moremore", MORE);
		gr.setValue("ctac_trade_status", CTAC_TRADE_STATUS);

        // Insert the record into the table
        var sysId = gr.insert();

        // Log the sys_id of the newly created record
        if (sysId) {
            gs.info('WPB Error Record inserted successfully with sys_id: ' + sysId);
        } else {
            gs.info('WPB Error Failed to insert the record.');
        }


        emailBody = str_header + str_playload;
        return emailBody;

    }

    function waitEmailRecord() {
        try {
            var grEmail = new GlideRecord('sys_email');
            grEmail.initialize();
            grEmail.addQuery('state', 'ready');
            grEmail.addQuery('type', 'send-ready');
            grEmail.addQuery('subject', 'CONTAINS', 'demo');
            grEmail.query();
            if (grEmail.next()) {
                gs.info("nicky_demo: grEmail :" + grEmail.sys_id);
                return grEmail;
            } else {
                return null;
            }
        } catch (ex) {
            var message = ex.getMessage();
            gs.error('nicky_demo: ' + message);
            return null;
        }
    }



})(request, response);
